_RENDER_HELPER_CODE = '        def _fmt_delta(metric: str, val: Any) -> str:\r\n            x = pd.to_numeric(val, errors="coerce")\r\n            if pd.isna(x):\r\n                return ""\r\n            xv = float(x)\r\n            m = str(metric or "").lower()\r\n            if "bps" in m:\r\n                return f"{xv:+.0f} bps"\r\n            if "share" in m and abs(xv) < 100:\r\n                sign = "+" if xv > 0 else "-" if xv < 0 else ""\r\n                return f"{sign}${abs(xv):,.2f}/sh"\r\n            if any(k in m for k in ["margin", "yoy", "growth", "yield"]) and abs(xv) <= 5:\r\n                return f"{xv*100:+.1f}%"\r\n            if abs(xv) >= 1_000_000:\r\n                sign = "+" if xv > 0 else "-" if xv < 0 else ""\r\n                return f"{sign}${abs(xv)/1e6:,.1f}m"\r\n            sign = "+" if xv > 0 else "-" if xv < 0 else ""\r\n            return f"{sign}{abs(xv):,.2f}"\r\n\r\n\r\n        def _block_header_writer(_ws: Any, row_idx: int, _qd: date, _max_col: int) -> int:\r\n            theme = _get_analysis_sheet_style_bundle()\r\n            hdr_fill = copy(theme["header_fill"])\r\n            thin_border = copy(theme["thin_border"])\r\n            labels = {2: "Category", 3: "Note", 4: "Metric"}\r\n            for cc in range(1, _max_col + 1):\r\n                cell = _ws.cell(row=row_idx, column=cc, value=labels.get(cc))\r\n                cell.font = Font(bold=True, size=11, color=str(theme["text_dark"]))\r\n                cell.fill = hdr_fill\r\n                cell.alignment = Alignment(horizontal="left", vertical="center")\r\n                cell.border = thin_border\r\n            return row_idx + 1\r\n\r\n        def _humanize_metric_label(raw_metric: Any) -> str:\r\n            metric = str(raw_metric or "").strip()\r\n            if not metric:\r\n                return ""\r\n            if "|" in metric:\r\n                parts = [part.strip() for part in metric.split("|")]\r\n                return " | ".join([part for part in parts if part])\r\n            metric_lower = metric.lower()\r\n            friendly_map = {\r\n                "adj_ebitda_yoy": "Adjusted EBITDA YoY",\r\n                "adj_ebit_yoy": "Adjusted EBIT YoY",\r\n                "ebitda_margin_ttm_yoy_bps": "EBITDA margin TTM YoY (bps)",\r\n                "ebitda_margin_yoy_bps": "EBITDA margin YoY (bps)",\r\n                "fcf_ttm_delta_yoy": "FCF TTM Δ YoY",\r\n                "fcf_ttm_delta_qoq": "FCF TTM Δ QoQ",\r\n                "fcf_yield_delta_yoy": "FCF yield Δ YoY",\r\n                "revenue_yoy": "Revenue YoY",\r\n                "adj_eps_yoy": "Adjusted EPS YoY",\r\n                "debt_action": "Debt action",\r\n                "capital_allocation_tone": "Capital allocation tone",\r\n                "capital_allocation_executed": "Capital allocation executed",\r\n                "pricing_mix_volume": "Pricing / mix / volume",\r\n                "margin_driver": "Margin driver",\r\n                "sg&a_driver": "SG&A driver",\r\n                "r&d_driver": "R&D driver",\r\n                "corp_exp_driver": "Corporate expense driver",\r\n                "other_expense_driver": "Other expense driver",\r\n                "restructuring_driver": "Restructuring driver",\r\n                "pension_driver": "Pension driver",\r\n            }\r\n            if metric_lower in friendly_map:\r\n                return friendly_map[metric_lower]\r\n            if metric_lower in {"strategic milestone", "debt reduction", "guidance", "program", "note"}:\r\n                return metric.title() if metric_lower == "note" else metric\r\n            pretty = metric.replace("_", " ").replace("/", " / ").strip()\r\n            pretty = re.sub(r"\\s+", " ", pretty)\r\n            pretty = pretty.title()\r\n            pretty = pretty.replace("Yoy", "YoY").replace("Qoq", "QoQ").replace("Ttm", "TTM")\r\n            pretty = pretty.replace("Ebitda", "EBITDA").replace("Ebit", "EBIT").replace("Fcf", "FCF")\r\n            pretty = pretty.replace("Bps", "bps").replace("Adj ", "Adjusted ")\r\n            return pretty\r\n\r\n        def _delta_context_label(metric_tag: Any, metric_display: Any, snippet: Any) -> str:\r\n            txt = str(snippet or "")\r\n            txt_low = txt.lower()\r\n            if re.search(r"\\bYoY\\b", txt, re.I):\r\n                return ""\r\n            if re.search(r"\\bQoQ\\b", txt, re.I):\r\n                return ""\r\n            tag_low = str(metric_tag or "").strip().lower()\r\n            disp_low = str(metric_display or "").strip().lower()\r\n            combined = " ".join([part for part in [tag_low, disp_low] if part]).strip()\r\n            if not combined:\r\n                return ""\r\n            if "yoy" in combined:\r\n                return "YoY"\r\n            if "qoq" in combined:\r\n                return "QoQ"\r\n            return ""\r\n\r\n        def _short_operational_status_phrase(item: Dict[str, Any]) -> str:\r\n            src = dict(item.get("source") or {})\r\n            src_blob = " ".join(\r\n                [\r\n                    str(src.get("source_type") or ""),\r\n                    str(src.get("form") or ""),\r\n                    str(src.get("doc") or ""),\r\n                ]\r\n            )\r\n            if not re.search(r"(earnings_release|press_release|presentation|slides|transcript)", src_blob, re.I):\r\n                return ""\r\n            txt = glx_normalize_text(str(item.get("text_full") or item.get("comment_full_text") or ""))\r\n            if not txt or int(_text_fragment_penalty(txt) or 0) > 1:\r\n                return ""\r\n            low = txt.lower()\r\n            metric_blob = " ".join(\r\n                [\r\n                    str(item.get("_metric_display") or ""),\r\n                    str(item.get("metric_canon") or ""),\r\n                    str(item.get("metric_tag") or ""),\r\n                    str(item.get("_theme_group") or ""),\r\n                ]\r\n            ).lower()\r\n            util_m = re.search(r"(?<!\\d)(\\d{2,3}(?:\\.\\d+)?)\\s*%\\*?", txt)\r\n            if util_m and (\r\n                re.search(r"\\b(utilization|operating rate|capacity utilization|stated capacity|production at)\\b", low)\r\n                or (\r\n                    "utilization" in metric_blob\r\n                    and re.search(r"\\b(ethanol|operating plants|production at|stated capacity|capacity utilization)\\b", low)\r\n                )\r\n            ):\r\n                if re.search(r"\\b(operating ethanol plants|operating plants|plants)\\b", low):\r\n                    return f"Utilization {util_m.group(1)}% across operating plants"\r\n                return f"Utilization {util_m.group(1)}% of stated capacity"\r\n            if (\r\n                ("risk management" in metric_blob or "risk management" in low)\r\n                and re.search(r"\\b(margins?|cash flow)\\b", low)\r\n                and re.search(r"\\b(support|supports|lock in|protect)\\b", low)\r\n            ):\r\n                return "Risk management supports margins and cash flow"\r\n            if re.search(r"\\byork\\b", low) and re.search(r"\\b(fully operational|fully online)\\b", low):\r\n                return "York carbon capture fully operational"\r\n            if (\r\n                re.search(r"\\bcentral city\\b", low)\r\n                and re.search(r"\\bwood river\\b", low)\r\n                and re.search(r"\\bonline\\b", low)\r\n                and re.search(r"\\bramping\\b", low)\r\n            ):\r\n                return "Central City and Wood River online and ramping"\r\n            if re.search(r"\\badvantage nebraska\\b", low) and re.search(r"\\b(fully operational|fully online)\\b", low):\r\n                return "Advantage Nebraska fully operational"\r\n            if re.search(r"\\b45z\\b", low) and re.search(r"\\bagreement executed\\b", low) and re.search(r"\\bnebraska\\b", low):\r\n                return "45Z agreement executed for Nebraska production"\r\n            if re.search(r"\\brins?\\b", low) and re.search(r"\\bcrush margin\\b", low) and re.search(r"\\b(sale|benefit|benefited|inclusive)\\b", low):\r\n                return "RIN sale benefited crush margin"\r\n            return ""\r\n\r\n        def _gpre_final_visible_note_metric(item: Dict[str, Any], metric_display_in: str) -> str:\r\n            metric_txt = str(metric_display_in or "").strip()\r\n            blob = glx_normalize_text(\r\n                " | ".join(\r\n                    [\r\n                        metric_txt,\r\n                        str(item.get("_render_summary") or ""),\r\n                        str(item.get("text_full") or ""),\r\n                        str(item.get("bucket") or ""),\r\n                    ]\r\n                )\r\n            )\r\n            low = blob.lower()\r\n            if re.search(\r\n                r"\\b(non-core asset monetization|enhance liquidity|strengthen (?:the|our) balance sheet|liquidity enhancement)\\b",\r\n                low,\r\n                re.I,\r\n            ):\r\n                return "Liquidity / balance-sheet"\r\n            if re.search(r"\\b45z\\b", low, re.I) and re.search(r"\\bproductions? tax credits contributed\\b", low, re.I):\r\n                return "45Z value realized"\r\n            if re.search(r"\\brisk management\\b", low, re.I) and re.search(r"\\b(margins?|cash flow)\\b", low, re.I):\r\n                return "Risk management"\r\n            if re.search(r"\\bcrush margin\\b", low, re.I):\r\n                return "Crush margin"\r\n            if re.search(r"\\bissued an additional\\b", low, re.I) and re.search(r"\\bnotes due november 2030\\b", low, re.I):\r\n                return "Additional note issuance"\r\n            if re.search(r"\\bexchanged?\\b", low, re.I) and re.search(r"\\bnotes due 2027\\b", low, re.I):\r\n                return "Debt exchange"\r\n            if re.search(r"\\binterest expense\\b", low, re.I) and re.search(r"\\b(expected|annualized|2026)\\b", low, re.I):\r\n                return "Interest expense outlook"\r\n            if re.search(r"\\brepurchase authorization\\b", low, re.I):\r\n                return "Repurchase authorization"\r\n            if re.search(r"\\brepurchased?\\b.*\\bshares\\b", low, re.I):\r\n                return "Repurchase execution"\r\n            if re.search(r"\\b(restructuring costs?|cost reduction initiative)\\b", low, re.I) and not re.search(\r\n                r"\\b(repurchase authorization|repurchas(?:e|ed)|share repurchase|interest expense|agreement|convertible|notes due)\\b",\r\n                low,\r\n                re.I,\r\n            ):\r\n                return "One-time items / restructuring"\r\n            if re.search(r"\\b(cost reductions?|cost savings|annualized savings target|annualized savings|run-rate savings)\\b", low, re.I):\r\n                return "Cost savings target"\r\n            if re.search(r"\\bfully operational\\b", low, re.I) and re.search(r"\\b(central city|wood river|york)\\b", low, re.I):\r\n                return "Carbon capture operational milestone"\r\n            if re.search(r"\\b45z\\b", low, re.I) and re.search(r"\\bagreement\\b", low, re.I):\r\n                return "45Z agreement update"\r\n            if re.search(r"\\badvantage nebraska\\b", low, re.I) and re.search(r"\\bebitda opportunity\\b", low, re.I):\r\n                return "Advantage Nebraska EBITDA opportunity"\r\n            if re.search(r"\\bnet debt\\b", low, re.I):\r\n                return "Net debt trend"\r\n            if re.search(r"\\bfcf\\b", low, re.I):\r\n                return "FCF trend"\r\n            if re.search(r"\\badjusted ebitda\\b", low, re.I) and re.search(r"\\byoy\\b", low, re.I):\r\n                return "Adjusted EBITDA"\r\n            return _gpre_clean_visible_note_metric(metric_txt, blob, item) or metric_txt\r\n\r\n        def _gpre_metric_from_visible_note_text(note_text_in: Any, metric_display_in: str) -> str:\r\n            metric_txt = str(metric_display_in or "").strip()\r\n            blob = glx_normalize_text(" | ".join([metric_txt, str(note_text_in or "")]))\r\n            low = blob.lower()\r\n            if re.search(\r\n                r"\\b(non-core asset monetization|enhance liquidity|strengthen (?:the|our) balance sheet|liquidity enhancement)\\b",\r\n                low,\r\n                re.I,\r\n            ):\r\n                return "Liquidity / balance-sheet"\r\n            if re.search(r"\\b45z\\b", low, re.I) and re.search(r"\\bproductions? tax credits contributed\\b", low, re.I):\r\n                return "45Z value realized"\r\n            if re.search(r"\\brisk management\\b", low, re.I) and re.search(r"\\b(margins?|cash flow)\\b", low, re.I):\r\n                return "Risk management"\r\n            if re.search(r"\\bcrush margin\\b", low, re.I):\r\n                return "Crush margin"\r\n            if re.search(r"\\bissued an additional\\b", low, re.I) and re.search(r"\\bnotes due november 2030\\b", low, re.I):\r\n                return "Additional note issuance"\r\n            if re.search(r"\\bexchanged?\\b", low, re.I) and re.search(r"\\bnotes due 2027\\b", low, re.I):\r\n                return "Debt exchange"\r\n            if re.search(r"\\binterest expense\\b", low, re.I) and re.search(r"\\b(expected|annualized|2026)\\b", low, re.I):\r\n                return "Interest expense outlook"\r\n            if re.search(r"\\brepurchase authorization\\b", low, re.I):\r\n                return "Repurchase authorization"\r\n            if re.search(r"\\brepurchased?\\b.*\\bshares\\b", low, re.I):\r\n                return "Repurchase execution"\r\n            if re.search(r"\\b(restructuring costs?|cost reduction initiative)\\b", low, re.I) and not re.search(\r\n                r"\\b(repurchase authorization|repurchas(?:e|ed)|share repurchase|interest expense|agreement|convertible|notes due)\\b",\r\n                low,\r\n                re.I,\r\n            ):\r\n                return "One-time items / restructuring"\r\n            if re.search(r"\\b(cost reductions?|cost savings|annualized savings target|annualized savings|run-rate savings)\\b", low, re.I):\r\n                return "Cost savings target"\r\n            if re.search(r"\\bfully operational\\b", low, re.I) and re.search(r"\\b(central city|wood river|york)\\b", low, re.I):\r\n                return "Carbon capture operational milestone"\r\n            if re.search(r"\\b45z\\b", low, re.I) and re.search(r"\\bagreement\\b", low, re.I):\r\n                return "45Z agreement update"\r\n            if re.search(r"\\badvantage nebraska\\b", low, re.I) and re.search(r"\\bebitda opportunity\\b", low, re.I):\r\n                return "Advantage Nebraska EBITDA opportunity"\r\n            return _gpre_normalize_metric_label(metric_txt, blob)\r\n\r\n        def _gpre_visible_bucket_metric_local(\r\n            item: Dict[str, Any],\r\n            bucket_in: Any,\r\n            metric_display_in: Any,\r\n            note_text_in: Any,\r\n        ) -> Tuple[str, str]:\r\n            bucket_txt = str(bucket_in or "").strip()\r\n            metric_txt = str(metric_display_in or "").strip()\r\n            note_blob = glx_normalize_text(str(note_text_in or ""))\r\n            if re.search(r"\\b45z\\b", note_blob, re.I) and re.search(r"\\bproductions? tax credits contributed\\b", note_blob, re.I):\r\n                bucket_txt = "Results / drivers"\r\n            if re.search(r"\\brestructuring costs?\\b", note_blob, re.I) and re.search(r"\\bcost reduction initiative\\b", note_blob, re.I):\r\n                bucket_txt = "Results / drivers"\r\n                metric_txt = "One-time items / restructuring"\r\n            metric_txt = _gpre_metric_from_visible_note_text(note_blob, metric_txt)\r\n            if metric_txt == "Crush margin":\r\n                bucket_txt = "Results / drivers / better vs prior"\r\n            elif metric_txt == "Risk management":\r\n                bucket_txt = "Guidance / outlook"\r\n            elif metric_txt == "45Z value realized":\r\n                bucket_txt = "Results / drivers"\r\n            elif metric_txt == "45Z plant qualification readiness":\r\n                bucket_txt = "Guidance / outlook"\r\n            elif metric_txt == "Liquidity / balance-sheet" and re.search(\r\n                r"\\b(non-core asset monetization|enhance liquidity|strengthen (?:the|our) balance sheet)\\b",\r\n                note_blob,\r\n                re.I,\r\n            ):\r\n                bucket_txt = "Programs / initiatives / management framing"\r\n            return bucket_txt, metric_txt\r\n\r\n        def _row_writer(_ws: Any, row_idx: int, qd: date, item: Dict[str, Any]) -> None:\r\n            item = capital_return_normalize_note_item(item)\r\n            bucket = str(item.get("bucket") or "")\r\n            metric_tag = str(item.get("metric_tag") or "").strip()\r\n            delta = _fmt_delta(metric_tag, item.get("metric_value"))\r\n            badge = str(item.get("change_badge") or "").strip().upper()\r\n            txt_full = str(item.get("text_full") or "")\r\n            status_phrase = _short_operational_status_phrase(item) if badge != "DROPPED" else ""\r\n            if status_phrase:\r\n                snippet = status_phrase\r\n            elif bucket == "What changed" and badge == "DROPPED":\r\n                sent_parts = glx_split_sentences(txt_full) or [txt_full]\r\n                snippet = qn_compact_snippet(sent_parts[0], 180)\r\n                num_toks = re.findall(r"(?<![A-Za-z])[-+]?\\$?\\d[\\d,]*\\.?\\d*(?:%|m|mm|bn|b|x)?", txt_full)\r\n                if len(num_toks) > 2:\r\n                    lbl_seed = metric_tag if metric_tag and metric_tag.lower() not in {"dropped themes", "dropped theme"} else ""\r\n                    if not lbl_seed:\r\n                        lbl_seed = re.sub(r"(?<![A-Za-z])[-+]?\\$?\\d[\\d,]*\\.?\\d*(?:%|m|mm|bn|b|x)?", " ", sent_parts[0])\r\n                    lbl = _clean_dropped_label(lbl_seed)\r\n                    if lbl:\r\n                        snippet = f"Dropped theme: {lbl}"\r\n                    else:\r\n                        snippet = "Dropped theme (no label available)" if str(item.get("comment_full_text") or txt_full).strip() else ""\r\n            else:\r\n                snippet_max = 300\r\n                snippet = qn_compact_snippet(txt_full, snippet_max)\r\n            fs_q = str(item.get("first_seen_quarter_end") or "").strip()\r\n            ls_q = str(item.get("last_seen_quarter_end") or "").strip()\r\n            ls_num_q = str(item.get("last_seen_numeric_quarter_end") or "").strip()\r\n            ls_txt_q = str(item.get("last_seen_text_quarter_end") or "").strip()\r\n            backfill_label = str(item.get("backfill_label") or "").strip()\r\n            stated_tag = ""\r\n            if fs_q and ls_q and fs_q != str(qd):\r\n                fs_lbl = _q_label(fs_q)\r\n                ls_lbl = _q_label(ls_q)\r\n                stated_tag = f" | stated {fs_lbl}->{ls_lbl}" if fs_lbl != ls_lbl else f" | stated {fs_lbl}"\r\n            if backfill_label:\r\n                stated_tag = f"{stated_tag} | {backfill_label}".strip(" |")\r\n                if stated_tag:\r\n                    stated_tag = f" | {stated_tag}"\r\n            txt_low = str(item.get("text_full") or "").lower()\r\n            gtype = str(item.get("guidance_type") or "").lower()\r\n            pbi_metric_override = str(item.get("_metric_display") or "").strip() if is_pbi_profile else ""\r\n            if is_pbi_profile and re.search(r"\\boperating expenses declined\\b", txt_low, re.I) and re.search(r"\\byoy\\b", txt_low, re.I):\r\n                bucket = "Results / drivers / better vs prior"\r\n                pbi_metric_override = "Adjusted EBIT / margin"\r\n            runrate_row = "cost savings" in str(metric_tag).lower() and (("run-rate" in txt_low) or gtype in {"run-rate", "ongoing"})\r\n            if is_pbi_profile and pbi_metric_override and pbi_metric_override.lower() not in {"management target", "tone | corporate"}:\r\n                prefix_metric = pbi_metric_override\r\n            elif runrate_row:\r\n                fs_lbl = _q_label(fs_q) if fs_q else "N/A"\r\n                ls_lbl = _q_label(ls_q) if ls_q else "N/A"\r\n                prefix_metric = f"Run-rate | stated {fs_lbl} | last seen {ls_lbl}"\r\n                if ls_num_q:\r\n                    prefix_metric = f"{prefix_metric} | numeric last {_q_label(ls_num_q)}"\r\n            elif bucket == "What changed":\r\n                prefix_metric = ""\r\n            elif bucket == "Tone / expectations":\r\n                if is_pbi_profile:\r\n                    pbi_metric = str(item.get("_metric_display") or "").strip()\r\n                    if pbi_metric and pbi_metric.lower() not in {"management target", "tone | corporate"}:\r\n                        prefix_metric = pbi_metric\r\n                    else:\r\n                        seg_name = str(item.get("segment") or "").strip()\r\n                        prefix_metric = f"Tone | {seg_name}" if seg_name else "Tone | Corporate"\r\n                else:\r\n                    seg_name = str(item.get("segment") or "").strip()\r\n                    prefix_metric = f"Tone | {seg_name}" if seg_name else "Tone | Corporate"\r\n            else:\r\n                prefix_metric = str(item.get("_metric_display") or "").strip() or (_humanize_metric_label(metric_tag) if metric_tag else "Note")\r\n            metric_display = prefix_metric\r\n            if is_gpre_profile:\r\n                metric_display = _gpre_final_visible_note_metric(item, metric_display)\r\n            if stated_tag and metric_display:\r\n                metric_display = f"{metric_display}{stated_tag}"\r\n            elif stated_tag:\r\n                metric_display = stated_tag.strip(" |")\r\n            badge_prefix = f"[{badge}] " if badge in {"NEW", "UPDATED", "DROPPED", "CONTINUED", "REAFFIRMED"} else ""\r\n            disp_body = str(item.get("_render_summary") or "").strip()\r\n            if not disp_body and is_pbi_profile:\r\n                disp_body = str(item.get("_pbi_compact_note") or "").strip()\r\n            preview_summary_local = _note_preview_summary_local(item, qd)\r\n            final_display_summary_local = _note_final_display_summary_local(item, qd)\r\n            if final_display_summary_local:\r\n                disp_body = final_display_summary_local\r\n            elif is_pbi_profile:\r\n                pbi_label = str(item.get("_metric_display") or "").strip() or metric_display\r\n                pbi_detail = _pbi_detail_preserving_note_summary_local(\r\n                    pbi_label,\r\n                    " | ".join(\r\n                        [\r\n                            str(item.get("comment_full_text") or ""),\r\n                            str(item.get("text_full") or ""),\r\n                            str(item.get("evidence_snippet") or ""),\r\n                            _evidence_snippet_blob_local(item),\r\n                            disp_body,\r\n                        ]\r\n                    ),\r\n                )\r\n                pbi_context_detail = _pbi_contextual_note_summary_local(\r\n                    pbi_label,\r\n                    qd,\r\n                    " | ".join(\r\n                        [\r\n                            str(item.get("comment_full_text") or ""),\r\n                            str(item.get("text_full") or ""),\r\n                            str(item.get("evidence_snippet") or ""),\r\n                            disp_body,\r\n                        ]\r\n                    ),\r\n                )\r\n                if pbi_context_detail:\r\n                    if (\r\n                        not pbi_detail\r\n                        or len(pbi_context_detail) > len(pbi_detail) + 4\r\n                        or (\r\n                            bool(re.search(r"(\\$|\\d|bps|from .* to)", pbi_context_detail, re.I))\r\n                            and not bool(re.search(r"(\\$|\\d|bps|from .* to)", pbi_detail, re.I))\r\n                        )\r\n                    ):\r\n                        pbi_detail = pbi_context_detail\r\n                if pbi_detail:\r\n                    generic_disp = bool(\r\n                        re.search(\r\n                            r"\\b(changed|continued|improved|updated|progressed)\\b",\r\n                            disp_body,\r\n                            re.I,\r\n                        )\r\n                    )\r\n                    disp_is_detailed = bool(re.search(r"(\\$|\\d|bps|from .* to)", disp_body, re.I))\r\n                    if not disp_body or generic_disp or not disp_is_detailed or len(pbi_detail) > len(disp_body):\r\n                        disp_body = pbi_detail\r\n                if pbi_label in _pbi_guidance_note_labels:\r\n                    guidance_blob = " | ".join(\r\n                        [\r\n                            str(item.get("comment_full_text") or ""),\r\n                            str(item.get("text_full") or ""),\r\n                            str(item.get("evidence_snippet") or ""),\r\n                            disp_body,\r\n                            preview_summary_local,\r\n                        ]\r\n                    )\r\n                    target_display = str(item.get("target_display") or "").strip() or _extract_pbi_target_display(guidance_blob, pbi_label)\r\n                    if _pbi_target_display_ok(target_display):\r\n                        period_norm = str(item.get("target_period_norm") or item.get("period_key") or "").strip()\r\n                        period_label = (\r\n                            _pbi_period_label_from_norm(period_norm, qd)\r\n                            or _pbi_guidance_period_label_from_text(guidance_blob)\r\n                            or _pbi_guidance_period_label_from_text(preview_summary_local)\r\n                            or _pbi_default_guidance_period_label(pbi_label, qd)\r\n                        )\r\n                        guidance_detail = _pbi_guidance_self_contained_summary(\r\n                            pbi_label,\r\n                            target_display,\r\n                            guidance_blob,\r\n                            period_label=period_label,\r\n                        )\r\n                        disp_is_generic = bool(\r\n                            re.search(r"\\b(target|updated target|tracking midpoint|tracking low end)\\b", disp_body, re.I)\r\n                        )\r\n                        if guidance_detail and (not disp_body or disp_is_generic):\r\n                            disp_body = guidance_detail\r\n            if not disp_body:\r\n                disp_body = snippet\r\n            if is_pbi_profile:\r\n                guidance_alignment_blob = " | ".join(\r\n                    [\r\n                        str(item.get("text_full") or ""),\r\n                        str(item.get("evidence_snippet") or ""),\r\n                        _evidence_snippet_blob_local(item),\r\n                        str(preview_summary_local or ""),\r\n                        str(final_display_summary_local or ""),\r\n                        str(disp_body or ""),\r\n                    ]\r\n                )\r\n                current_pbi_label = str(item.get("_metric_display") or metric_display or "").strip()\r\n                current_target_display = str(item.get("target_display") or "").strip() or _extract_pbi_target_display(\r\n                    guidance_alignment_blob,\r\n                    current_pbi_label,\r\n                )\r\n                aligned_pbi_label = _pbi_relabel_generic_guidance_note(\r\n                    current_pbi_label,\r\n                    guidance_alignment_blob,\r\n                    current_target_display,\r\n                )\r\n                if aligned_pbi_label in _pbi_guidance_note_labels and aligned_pbi_label != current_pbi_label:\r\n                    item["_metric_display"] = aligned_pbi_label\r\n                    repaired_bucket = _pbi_bucket_for_label_local(aligned_pbi_label, item.get("bucket") or bucket)\r\n                    if repaired_bucket:\r\n                        item["bucket"] = repaired_bucket\r\n                        bucket = repaired_bucket\r\n                    metric_display = aligned_pbi_label + (stated_tag or "")\r\n                    if _pbi_target_display_ok(current_target_display):\r\n                        period_norm = str(item.get("target_period_norm") or item.get("period_key") or "").strip()\r\n                        period_label = (\r\n                            _pbi_period_label_from_norm(period_norm, qd)\r\n                            or _pbi_guidance_period_label_from_text(guidance_alignment_blob)\r\n                            or _pbi_default_guidance_period_label(aligned_pbi_label, qd)\r\n                        )\r\n                        repaired_guidance_summary = _pbi_guidance_self_contained_summary(\r\n                            aligned_pbi_label,\r\n                            current_target_display,\r\n                            guidance_alignment_blob,\r\n                            period_label=period_label,\r\n                        )\r\n                        if repaired_guidance_summary:\r\n                            disp_body = repaired_guidance_summary\r\n                if str(item.get("_metric_display") or metric_display or "").strip() == "FCF improvement":\r\n                    forced_fcf_note = _pbi_forced_release_backed_fcf_note_for_qd(qd)\r\n                    if forced_fcf_note is not None:\r\n                        disp_body = str(forced_fcf_note.get("summary") or disp_body)\r\n                        metric_display = "Quarterly FCF"\r\n                        item["_metric_display"] = "Quarterly FCF"\r\n                        item["metric_display"] = "Quarterly FCF"\r\n                        item["comment_full_text"] = str(forced_fcf_note.get("comment_full_text") or item.get("comment_full_text") or "")\r\n                        item["text_full"] = str(forced_fcf_note.get("summary") or item.get("text_full") or "")\r\n                        item["source"] = dict(forced_fcf_note.get("source") or item.get("source") or {})\r\n                    elif re.search(r"^\\s*free cash flow\\b", str(disp_body or ""), re.I):\r\n                        metric_display = "Quarterly FCF"\r\n                        item["_metric_display"] = "Quarterly FCF"\r\n                        item["metric_display"] = "Quarterly FCF"\r\n                pbi_results_blob = glx_normalize_text(\r\n                    " | ".join(\r\n                        [\r\n                            str(txt_full or ""),\r\n                            str(preview_summary_local or ""),\r\n                            str(final_display_summary_local or ""),\r\n                            str(disp_body or ""),\r\n                        ]\r\n                    )\r\n                )\r\n                if re.search(r"\\boperating expenses declined\\b", pbi_results_blob, re.I) and re.search(r"\\byoy\\b", pbi_results_blob, re.I):\r\n                    bucket = "Results / drivers / better vs prior"\r\n                    item["bucket"] = bucket\r\n                    metric_display = "Adjusted EBIT / margin"\r\n                    item["_metric_display"] = "Adjusted EBIT / margin"\r\n                    item["metric_display"] = "Adjusted EBIT / margin"\r\n            disp = f"{badge_prefix}{disp_body}".strip()\r\n            if delta:\r\n                delta_context = _delta_context_label(metric_tag, metric_display, disp)\r\n                if delta_context:\r\n                    disp = f"{disp} {delta_context} \\u0394 {delta}"\r\n                else:\r\n                    disp = f"{disp} \\u0394 {delta}"\r\n            if is_gpre_profile:\r\n                bucket, metric_display = _gpre_visible_bucket_metric_local(item, bucket, metric_display, disp)\r\n                if str(metric_display or "").strip() == "Risk management":\r\n                    official_risk_note = _gpre_official_risk_management_note_local(qd)\r\n                    transcript_risk_note = _gpre_transcript_risk_management_note_local(qd) if not dict((official_risk_note or {}).get("source") or {}) else {}\r\n                    selected_risk_note = official_risk_note or transcript_risk_note\r\n                    official_risk_summary = glx_normalize_text(str((selected_risk_note or {}).get("text") or ""))\r\n                    risk_blob = " | ".join(\r\n                        [\r\n                            str(item.get("comment_full_text") or ""),\r\n                            str(item.get("text_full") or ""),\r\n                            str(item.get("evidence_snippet") or ""),\r\n                            _evidence_snippet_blob_local(item),\r\n                            disp,\r\n                        ]\r\n                    )\r\n                    if (\r\n                        not official_risk_summary\r\n                        and re.search(r"\\bdisciplined risk management strategy continues to support\\b", risk_blob, re.I)\r\n                    ):\r\n                        official_risk_summary = "Disciplined risk management strategy continues to support first quarter margins and cash flow."\r\n                    if official_risk_summary:\r\n                        disp = f"{badge_prefix}{official_risk_summary}".strip()\r\n                        item["_render_summary"] = official_risk_summary\r\n                        item["_render_summary_locked"] = True\r\n                        item["text_full"] = official_risk_summary\r\n                        item["comment_full_text"] = str((selected_risk_note or {}).get("comment_full_text") or official_risk_summary)\r\n                        if dict((selected_risk_note or {}).get("source") or {}):\r\n                            item["source"] = dict((selected_risk_note or {}).get("source") or {})\r\n            disp = capital_return_normalize_new_prefix(disp)\r\n            visible_capital_return_row = capital_return_normalize_note_item(\r\n                {\r\n                    "note": disp,\r\n                    "bucket": bucket,\r\n                    "category": bucket,\r\n                    "metric_display": metric_display,\r\n                    "_metric_display": metric_display,\r\n                }\r\n            )\r\n            disp = str(visible_capital_return_row.get("note") or disp)\r\n            bucket = str(visible_capital_return_row.get("bucket") or bucket)\r\n            metric_display = str(\r\n                visible_capital_return_row.get("_metric_display")\r\n                or visible_capital_return_row.get("metric_display")\r\n                or metric_display\r\n            )\r\n            _ws.cell(row=row_idx, column=2, value=bucket)\r\n            c_note = _ws.cell(row=row_idx, column=3, value=disp)\r\n            c_note.alignment = Alignment(wrap_text=True, vertical="top")\r\n            c_note.font = Font(size=13, color="000000")\r\n            sev = str(item.get("severity") or "").lower()\r\n            if "fail" in sev:\r\n                c_note.fill = PatternFill("solid", fgColor="FFC7CE")\r\n            elif "warn" in sev:\r\n                c_note.fill = PatternFill("solid", fgColor="FFEB9C")\r\n\r\n            c_metric = _ws.cell(row=row_idx, column=4, value=metric_display)\r\n            c_metric.alignment = Alignment(wrap_text=True, vertical="top")\r\n            c_metric.font = Font(size=11, color="000000")\r\n\r\n            src = dict(item.get("source") or {})\r\n            src_bits = [\r\n                f"Source: {src.get(\'source_type\') or \'n/a\'}",\r\n                f"form={src.get(\'form\') or \'\'}",\r\n                f"accn={src.get(\'accn\') or \'\'}",\r\n                f"doc={src.get(\'doc\') or \'\'}",\r\n                f"section={src.get(\'section\') or \'\'}",\r\n                f"score={float(item.get(\'score\') or 0.0):.1f}",\r\n                f"as_of={item.get(\'as_of_quarter_end\') or \'\'}",\r\n                f"doc_end={item.get(\'source_doc_end\') or \'\'}",\r\n                f"first_seen={item.get(\'first_seen_quarter_end\') or \'\'}",\r\n                f"last_seen={item.get(\'last_seen_quarter_end\') or \'\'}",\r\n                f"last_seen_numeric={item.get(\'last_seen_numeric_quarter_end\') or \'\'}",\r\n                f"last_seen_text={item.get(\'last_seen_text_quarter_end\') or \'\'}",\r\n                f"mention_kind={item.get(\'mention_kind\') or \'\'}",\r\n                f"candidate_type={item.get(\'candidate_type\') or \'\'}",\r\n                f"theme={item.get(\'theme_key\') or \'\'}",\r\n                f"target_period={item.get(\'target_period_norm\') or \'\'}",\r\n                f"why_chosen=score:{float(item.get(\'score\') or 0.0):.1f},forward:{bool(item.get(\'has_forward_intent\'))}",\r\n            ]\r\n            comment_payload = str(item.get("comment_full_text") or item.get("text_full") or "")\r\n            comment_txt = f"Evidence: {comment_payload}\\\\n\\\\n" + " | ".join([x for x in src_bits if x])\r\n            try:\r\n                _set_cell_comment_local(c_note, comment_txt)\r\n            except Exception:\r\n                pass\r\n\r\n            c_width = _ws.column_dimensions["C"].width\r\n            if c_width in (None, 0) or float(c_width) < 40.0:\r\n                c_width = qn_note_col_width_default\r\n            row_h = _estimate_wrapped_row_height(\r\n                disp,\r\n                float(c_width),\r\n                base_height=18.0,\r\n                line_height=14.5,\r\n                min_lines=1,\r\n                max_lines=6,\r\n            )\r\n            cap_h = 78.0\r\n            if bucket in {"Tone / expectations", "Programs / initiatives / management framing", "What changed"}:\r\n                cap_h = 92.0\r\n            elif bucket in {\r\n                "Results / drivers",\r\n                "Results / drivers / better vs prior",\r\n                "Programs / initiatives",\r\n                "Operations / commercialization / milestones",\r\n            }:\r\n                cap_h = 88.0\r\n            elif bucket == "Guidance / outlook":\r\n                cap_h = 84.0\r\n            if row_h > cap_h:\r\n                row_h = cap_h\r\n            _ws.row_dimensions[row_idx].height = row_h\n'

_NESTED_HELPER_INDENT = "        "


def _dedent_render_helper_code(code: str) -> str:
    return "\n".join(
        line[len(_NESTED_HELPER_INDENT):] if line.startswith(_NESTED_HELPER_INDENT) else line
        for line in code.splitlines()
    )


def _render_runtime(deps: QuarterNotesUiRenderDeps) -> Dict[str, Any]:
    env: Dict[str, Any] = dict(deps.runtime)
    env.update(
        {
            "Any": Any,
            "Dict": Dict,
            "Mapping": Mapping,
            "MutableMapping": MutableMapping,
            "Sequence": Sequence,
            "Tuple": Tuple,
            "Alignment": Alignment,
            "Font": Font,
            "PatternFill": PatternFill,
            "copy": copy,
            "date": date,
            "pd": pd,
            "re": re,
            "ws": deps.ws,
            "quarters": deps.quarters,
            "rows_by_quarter": deps.rows_by_quarter,
            "ticker": deps.ticker,
            "is_pbi_profile": deps.is_pbi_profile,
            "is_gpre_profile": deps.is_gpre_profile,
            "is_anf_profile": deps.is_anf_profile,
            "qn_note_col_width_default": deps.qn_note_col_width_default,
        }
    )
    return env


def install_quarter_notes_ui_render_helpers(runtime: MutableMapping[str, Any]) -> MutableMapping[str, Any]:
    runtime.update(
        {
            "Any": Any,
            "Dict": Dict,
            "Mapping": Mapping,
            "MutableMapping": MutableMapping,
            "Sequence": Sequence,
            "Tuple": Tuple,
            "Alignment": Alignment,
            "Font": Font,
            "PatternFill": PatternFill,
            "copy": copy,
            "date": date,
            "pd": pd,
            "re": re,
        }
    )
    exec(_dedent_render_helper_code(_RENDER_HELPER_CODE), runtime)
    return runtime


def write_quarter_notes_ui_rendered_blocks(
    deps: QuarterNotesUiRenderDeps,
) -> QuarterNotesUiRenderResult:
    env = _render_runtime(deps)
    install_quarter_notes_ui_render_helpers(env)
    env["_render_stacked_quarter_blocks"](
        ws=deps.ws,
        quarters=deps.quarters,
        rows_by_quarter=deps.rows_by_quarter,
        max_col=4,
        block_title_fn=lambda qd: (env["_quarter_label_short"](qd) if deps.is_anf_profile else str(qd)),
        row_writer=env["_row_writer"],
        block_header_writer=env["_block_header_writer"],
        start_row=3,
        blank_row_between=False,
    )
    return QuarterNotesUiRenderResult(
        row_count=sum(len(list(rows)) for rows in deps.rows_by_quarter.values()),
        max_row=int(getattr(deps.ws, "max_row", 0) or 0),
    )
